setup.src/routes.js:
const loans = require('./loans');

function route(req, res) {
  if (req.method === 'POST' && req.url.startsWith('/loans')) return loans.borrow(req, res);
  res.writeHead(404).end();
}

module.exports = { route };

setup.src/loans.js:
const LOAN_DAYS = 14;

function dueDate(borrowedAt) {
  return new Date(Date.parse(borrowedAt) + LOAN_DAYS * 86400000).toISOString();
}

function borrow(req, res) {
  res.writeHead(201, { 'content-type': 'application/json' }).end(JSON.stringify({ due: dueDate(new Date().toISOString()) }));
}

module.exports = { borrow, dueDate };

